.ds-fix:disabled { cursor: default; }
.ds-fix:active:not(:disabled) { transform: scale(0.97); }
.ds-fix:focus-visible { outline: var(--ds-border-focus) solid var(--ds-color-edge-accent); outline-offset: var(--ds-border-focus); }
